files.content:
:root {
  --bg: #1a1c2c;
  --card: #2a2d44;
  --text: #f4f4f4;
  --accent: #f4b41a;
  --accent-dark: #c78e0e;
  --correct: #4caf50;
  --wrong: #e53935;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, sans-serif;
  font-size: 18px;
  color: var(--text);
  padding: 16px;
  image-rendering: pixelated;
}

.quiz-card {
  background: var(--card);
  border: 4px solid var(--accent);
  border-radius: 0;
  padding: 32px 24px;
  width: 100%;
  max-width: 420px;
  text-align: center;
  box-shadow: 8px 8px 0 rgba(0,0,0,0.4);
}

h1 {
  margin: 0 0 16px;
  font-size: 1.6rem;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--accent);
}

.score-row {
  display: flex;
  align-items: baseline;
  justify-content: center;
  gap: 6px;
  margin-bottom: 20px;
}

#score {
  font-size: 2rem;
  font-weight: bold;
  color: var(--accent);
}

.score-label {
  font-size: 0.9rem;
  opacity: 0.8;
}

.question {
  font-size: 1.4rem;
  margin: 0 0 24px;
  min-height: 1.6em;
  font-weight: 600;
}

.answers {
  display: flex;
  gap: 16px;
  margin-bottom: 24px;
}

.answer-btn,
.control-btn {
  font-family: inherit;
  font-size: 1.1rem;
  font-weight: 600;
  padding: 14px 20px;
  border: 3px solid var(--accent);
  border-radius: 0;
  background: transparent;
  color: var(--text);
  cursor: pointer;
  transition: transform 0.05s, background 0.15s;
  flex: 1;
}

.answer-btn:hover,
.control-btn:hover:not(:disabled) {
  background: var(--accent);
  color: var(--bg);
}

.answer-btn:focus-visible,
.control-btn:focus-visible {
  outline: 3px solid var(--text);
  outline-offset: 3px;
}

.answer-btn:active:not(:disabled),
.control-btn:active:not(:disabled) {
  transform: translate(2px, 2px);
}

.answer-btn.correct { background: var(--correct); border-color: var(--correct); color: #fff; }
.answer-btn.wrong { background: var(--wrong); border-color: var(--wrong); color: #fff; }

.answer-btn:disabled,
.control-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.controls {
  display: flex;
  gap: 16px;
}

.control-btn {
  font-size: 1rem;
  padding: 12px 16px;
}

@media (max-width: 400px) {
  .quiz-card { padding: 24px 16px; }
  .answers, .controls { flex-direction: column; }
}

const questionEl = document.getElementById('question');
const answerA = document.getElementById('answer-a');
const answerB = document.getElementById('answer-b');
const scoreEl = document.getElementById('score');
const nextBtn = document.getElementById('next');
const restartBtn = document.getElementById('restart');

const questions = [
  { text: '2 + 2 = ?', a: '4', b: '5', correct: 'a' },
  { text: '3 + 3 = ?', a: '5', b: '6', correct: 'b' }
];

let current = 0;
let score = 0;
let answered = false;
let finished = false;

function render() {
  const q = questions[current];
  questionEl.textContent = q.text;
  answerA.textContent = q.a;
  answerB.textContent = q.b;
  answerA.disabled = false;
  answerB.disabled = false;
  answerA.classList.remove('correct', 'wrong');
  answerB.classList.remove('correct', 'wrong');
  answered = false;
  nextBtn.disabled = true;
  scoreEl.textContent = String(score);
}

function handleAnswer(choice) {
  if (answered || finished) return;
  answered = true;
  const q = questions[current];
  const chosenBtn = choice === 'a' ? answerA : answerB;
  const otherBtn = choice === 'a' ? answerB : answerA;
  answerA.disabled = true;
  answerB.disabled = true;
  if (q.correct === choice) {
    score += 1;
    scoreEl.textContent = String(score);
    chosenBtn.classList.add('correct');
  } else {
    chosenBtn.classList.add('wrong');
    otherBtn.classList.add('correct');
  }
  nextBtn.disabled = false;
}

function handleNext() {
  if (!answered) return;
  if (current === 0) {
    current = 1;
    render();
  } else {
    finished = true;
    questionEl.textContent = 'Finished';
    answerA.disabled = true;
    answerB.disabled = true;
    nextBtn.disabled = true;
  }
}

function handleRestart() {
  current = 0;
  score = 0;
  finished = false;
  render();
}

answerA.addEventListener('click', () => handleAnswer('a'));
answerB.addEventListener('click', () => handleAnswer('b'));
nextBtn.addEventListener('click', handleNext);
restartBtn.addEventListener('click', handleRestart);

render();
